// Package: Azure.AI.Search --version 1.*
// Package: Azure.Identity

using Azure;
using Azure.AI.Search;
using Azure.AI.Search.Models;
using Azure.Identity;

var endpoint = new Uri("https://your-search.search.windows.net/");
var credential = new DefaultAzureCredential();

var client = new SearchClient(endpoint, "your-index-name", credential);

var options = new SearchOptions
{
    Size = 5,
    VectorSearch = new VectorSearchOptions
    {
        Queries = { new VectorizedQuery(queryVector) { KNearestNeighborsCount = 5 } }
    }
};

var response = await client.SearchAsync<DocumentChunk>(
    "*",
    options,
    cancellationToken);

await foreach (var result in response.Value.GetResultsAsync(cancellationToken))
{
    Console.WriteLine($"{result.Document.Text} (score: {result.Score})");
}

public sealed record DocumentChunk(string Text, string DocumentId, int ChunkIndex);

// Package: Azure.AI.Inference --version 1.*
