using Azure.AI.Inference;
using Azure.Identity;
using Microsoft.Extensions.AI;
using Microsoft.Extensions.AI.Azure;

// Option 1: Microsoft.Extensions.AI.Azure abstraction
var endpoint = new Uri("https://your-aoai.openai.azure.com/");
var credential = new DefaultAzureCredential();
var chatClient = new AzureAIChatClient(endpoint, "gpt-4o", credential);

var response = await chatClient.GetResponseAsync(
    [new ChatMessage(ChatRole.User, "What is RAG?")],
    cancellationToken: ct);

Console.WriteLine(response.Messages.Last().Text);

// Option 2: Azure.AI.Inference direct client
var inferenceClient = new ChatCompletionsClient(
    endpoint,
    new DefaultAzureCredential());

var completion = await inferenceClient.CompleteAsync(
    new ChatCompletionsOptions
    {
        Messages = { new UserChatMessage("What is RAG?") },
        Model = "gpt-4o"
    },
    cancellationToken);

Console.WriteLine(completion.Value.Content);
